  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2017, 2019],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "AE rises from 0.929 in 2017 to 1.438 in 2019 (~+0.51 cumulative), with high levels of 1.329-1.438 in 2018-2019, then reverts to 0.914 in 2020",
      "confidence": 0.88,
      "evidence": [
        "artifacts/ae_ip_by_year.csv: 2017 AE 0.929, 2018 AE 1.329 (Actual 1783 vs Expected 1342), 2019 AE 1.438 (Actual 2072 vs Expected 1441), 2020 AE 0.914",
        "two consecutive year-on-year increases over the 2017-2019 window (+0.400 then +0.109), indicating a sub-window upward move that later reverts rather than a single-year spike",
        "other IP years are broadly 0.885-0.937, and artifacts/ae_ip_termination.csv shows pooled termination A/E by diagnosis near 1.0, so this is not driven by a diagnosis-specific recovery-rate change"
      ],
      "recommended_action": "Investigate 2017-2019 IP claims in detail (claim dates, diagnosis, employer/broker, underwriting class, data/coding, one-off policy loading or fraud), validate the IP expected-claims and exposure model, and if the increase is confirmed, follow through with pricing/valuation adjustments and monitor 2025 for recurrence."
    }
  ]
}

